import{Z as i,e as t,f as o,a0 as r}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Migrating from Sprout Forms","description":"","frontmatter":{},"headers":[],"relativePath":"guides/migrations-upgrades/migrating-from-sprout-forms.md","filePath":"guides/migrations-upgrades/migrating-from-sprout-forms.md","lastUpdated":1782532814000}'),a={name:"guides/migrations-upgrades/migrating-from-sprout-forms.md"};function s(n,e,l,d,p,m){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="migrating-from-sprout-forms" tabindex="-1">Migrating from Sprout Forms <a class="header-anchor" href="#migrating-from-sprout-forms" aria-label="Permalink to &quot;Migrating from Sprout Forms&quot;">​</a></h1><p>If your Craft site uses <a href="https://sprout.barrelstrengthdesign.com/docs/forms/" target="_blank" rel="noreferrer">Sprout Forms</a>, Formie&#39;s migration tool copies forms, email notifications, and submissions into Formie without modifying Sprout data. Sprout Forms layouts are typically simpler than Freeform — migration is often straightforward with few unsupported field types.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Formie installed</li><li>Sprout Forms still installed and <strong>enabled</strong></li><li>Database backup before production migration</li></ul><h2 id="before-you-migrate" tabindex="-1">Before You Migrate <a class="header-anchor" href="#before-you-migrate" aria-label="Permalink to &quot;Before You Migrate&quot;">​</a></h2><ol><li><strong>Inventory forms</strong> — handles, notification rules, front-end embed locations</li><li><strong>Export Sprout submissions</strong> if you need CSV archives beyond what migration copies</li><li><strong>Run on staging</strong> with both plugins enabled</li><li><strong>Plan template updates</strong> — Sprout render syntax differs from Formie</li></ol><h2 id="run-the-migration" tabindex="-1">Run the Migration <a class="header-anchor" href="#run-the-migration" aria-label="Permalink to &quot;Run the Migration&quot;">​</a></h2><ol><li>Navigate to <strong>Formie → Settings → Migrations → Sprout Forms</strong></li><li>Select Sprout forms to migrate</li><li>Click <strong>Migrate Forms</strong></li><li>Review results — copied forms, notifications, submissions, and errors</li></ol><p>Sprout Forms data is not modified.</p><h2 id="handle-collisions" tabindex="-1">Handle Collisions <a class="header-anchor" href="#handle-collisions" aria-label="Permalink to &quot;Handle Collisions&quot;">​</a></h2><p>Duplicate handles get a numeric suffix — <code>contactForm</code> becomes <code>contactForm1</code> if Formie already owns <code>contactForm</code>. Rename in the Formie builder and update templates.</p><h2 id="unsupported-fields" tabindex="-1">Unsupported Fields <a class="header-anchor" href="#unsupported-fields" aria-label="Permalink to &quot;Unsupported Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sprout Forms field</th><th>Formie approach</th></tr></thead><tbody><tr><td>Private Notes</td><td>Use HTML cosmetic field or editor note — not a direct equivalent</td></tr><tr><td>Regular Expression</td><td>Use Single-Line Text with validation pattern</td></tr></tbody></table><p>Most common Sprout field types (Single Line, Paragraph, Dropdown, Email, Number, Checkboxes, Radio) migrate cleanly.</p><h2 id="after-migration-checklist" tabindex="-1">After Migration Checklist <a class="header-anchor" href="#after-migration-checklist" aria-label="Permalink to &quot;After Migration Checklist&quot;">​</a></h2><ul><li>Verify each form in the form builder</li><li>Update Twig from Sprout embed syntax to <code>craft.formie.renderForm()</code></li><li>Configure spam protection (<strong>Settings → Spam Protection</strong>) — Sprout&#39;s approach may differ</li><li>Set up email notifications if Sprout used different notification mechanics</li><li>Test front-end submit and admin notification delivery</li><li>Compare submission counts</li><li>Update any Sprout-specific reporting or exports to Formie submissions index</li></ul><h2 id="front-end-cutover" tabindex="-1">Front-End Cutover <a class="header-anchor" href="#front-end-cutover" aria-label="Permalink to &quot;Front-End Cutover&quot;">​</a></h2><p>Sprout templates often use:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">{# Sprout — replace after migration #}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.sproutForms.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;handle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>Formie equivalent:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;handle&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>For headless sites, follow <a href="/guides/frontend-headless/building-a-headless-contact-form-with-formie-react">Building a headless contact form with Formie React</a>.</p><p>Include Formie front-end assets — see <a href="/frontend/frontend-assets">Frontend Assets</a>. Sprout&#39;s JS/CSS do not carry over.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Migrated notifications become Formie email notifications. Verify:</p><ul><li><strong>From</strong> / <strong>Reply-To</strong> — see <a href="/guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails">deliverability guide</a></li><li>Variable tokens — Formie uses <a href="/developers/reference-tokens">field references</a>, not Sprout&#39;s token syntax; re-pick fields in the notification editor</li><li>Conditions — rebuild if Sprout used rule-based sending</li></ul><h2 id="when-to-keep-sprout-temporarily" tabindex="-1">When to Keep Sprout Temporarily <a class="header-anchor" href="#when-to-keep-sprout-temporarily" aria-label="Permalink to &quot;When to Keep Sprout Temporarily&quot;">​</a></h2><p>Run parallel if Sprout forms are embedded in hard-to-update legacy templates. Hide Sprout forms from navigation while Formie forms go live on new templates.</p><p>Uninstall Sprout Forms only after all active forms migrate and historical submissions are accessible in Formie (or exported).</p>`,29)])])}const c=i(a,[["render",s]]);export{h as __pageData,c as default};
